What is the output?

let x = 5;
const fn = () => x * 2;
x = 10;
console.log(fn());

What is printed to the console? (write both lines separated by a comma)

const add = (a, b) => a + b;
console.log(add(3, 4));
console.log(typeof add(3, 4));

What is the output?

function outer(x) {
  return function(y) {
    return x + y;
  };
}
const add5 = outer(5);
console.log(add5(3));

What are the three output lines? (write them separated by commas)

console.log(Boolean(0));
console.log(Boolean(""));
console.log(Boolean([]));

What is the output?

async function getValue() {
  const v = await Promise.resolve(42);
  console.log(v);
}
getValue();

What is the output order? (write the three letters separated by commas)

process.nextTick(() => console.log('A'));
Promise.resolve().then(() => console.log('B'));
console.log('C');

What is the output?

const arr = [1, 2, 3, 4];
const result = arr
  .filter(n => n % 2 === 0)
  .map(n => n * 10);
console.log(result);

What are the two output lines? (write them separated by a comma)

const obj = { a: 1, b: 2 };
const { a, ...rest } = obj;
console.log(a);
console.log(JSON.stringify(rest));

What are the two output lines? (write them separated by a comma)

const { EventEmitter } = require('events');
const e = new EventEmitter();
e.on('ping', (msg) => {
  console.log('Received:', msg);
});
e.emit('ping', 'hello');
e.emit('ping', 'world');

What is the output?

async function fetchData() {
  try {
    const r = await Promise.reject(
      new Error('Network error')
    );
    console.log(r);
  } catch(err) {
    console.log('Caught:', err.message);
  }
}
fetchData();

What is the output?

function makeCounter(start) {
  let count = start;
  return {
    inc: () => ++count,
    get: () => count
  };
}
const c = makeCounter(0);
c.inc(); c.inc(); c.inc();
console.log(c.get());

What is the output?

const nums = [1, 2, 3, 4, 5];
const sum = nums.reduce(
  (acc, n) => acc + n, 0
);
console.log(sum);

What is the output?

async function run() {
  const p1 = Promise.resolve('first');
  const p2 = Promise.resolve('second');
  const [a, b] = await Promise.all([p1, p2]);
  console.log(a, b);
}
run();

What are the two output lines? (write them separated by a comma)

class AppError extends Error {
  constructor(msg, code) {
    super(msg);
    this.name = 'AppError';
    this.code = code;
  }
}
try {
  throw new AppError('Oops', 404);
} catch(e) {
  console.log(e.name + ': ' + e.message);
  console.log(e.code);
}

Assume a POST /data request is received. What does the client receive as the response body?

const http = require('http');
const server = http.createServer(
  (req, res) => {
    if (req.method === 'POST' &&
        req.url === '/data') {
      res.writeHead(201, {
        'Content-Type': 'application/json'
      });
      res.end(
        JSON.stringify({ created: true })
      );
    }
  }
);
